import Compression
import Darwin
import Foundation

/// Offline IPv4/IPv6 → country lookup used for the peer flags.
///
/// The tables are generated by `Scripts/build-geoip.sh` from the DB-IP Lite
/// dataset (CC BY 4.0) and shipped inside the app: no peer address ever leaves
/// the machine. Private/LAN addresses and unknown ranges report no flag.
package enum GeoIP {
    private static let table: GeoIPTable? = {
        guard
            let url = Bundle.main.url(
                forResource: "country-v4",
                withExtension: "bin.z",
                subdirectory: "GeoIP"
            )
        else { return nil }
        return GeoIPTable.load(from: url)
    }()

    private static let tableV6: GeoIPv6Table? = {
        guard
            let url = Bundle.main.url(
                forResource: "country-v6",
                withExtension: "bin.z",
                subdirectory: "GeoIP"
            )
        else { return nil }
        return GeoIPv6Table.load(from: url)
    }()

    /// Two-letter country code for a peer endpoint such as `1.2.3.4:6881` or
    /// `[2001:db8::1]:6881`. Returns nil for private/LAN addresses and unknown
    /// ranges.
    package static func countryCode(forEndpoint endpoint: String) -> String? {
        if let address = ipv4Address(fromEndpoint: endpoint) {
            return isPrivate(address) ? nil : table?.countryCode(for: address)
        }
        guard let address = ipv6Address(fromEndpoint: endpoint) else { return nil }
        if let mapped = mappedIPv4(address) {
            return isPrivate(mapped) ? nil : table?.countryCode(for: mapped)
        }
        return isPrivate(address) ? nil : tableV6?.countryCode(for: address)
    }

    package static func isLocalEndpoint(_ endpoint: String) -> Bool {
        if let address = ipv4Address(fromEndpoint: endpoint) {
            return isPrivate(address)
        }
        guard let address = ipv6Address(fromEndpoint: endpoint) else { return false }
        if let mapped = mappedIPv4(address) {
            return isPrivate(mapped)
        }
        return isPrivate(address)
    }

    /// Regional-indicator flag for a two-letter code: `IT` → 🇮🇹.
    package static func flag(for code: String) -> String? {
        let scalars = Array(code.uppercased().unicodeScalars)
        guard scalars.count == 2 else { return nil }
        var result = String.UnicodeScalarView()
        for scalar in scalars {
            guard scalar.value >= 65, scalar.value <= 90,
                let flagScalar = UnicodeScalar(0x1F1E6 + scalar.value - 65)
            else {
                return nil
            }
            result.append(flagScalar)
        }
        return String(result)
    }

    package static func countryName(for code: String) -> String {
        Locale.current.localizedString(forRegionCode: code) ?? code
    }

    /// Parses the host part of an IPv4 peer endpoint. IPv6 forms are rejected
    /// here and handled by `ipv6Address(fromEndpoint:)`.
    package static func ipv4Address(fromEndpoint endpoint: String) -> UInt32? {
        guard !endpoint.hasPrefix("["), !endpoint.contains("::") else { return nil }
        let host =
            endpoint
            .split(separator: ":", maxSplits: 1, omittingEmptySubsequences: false)
            .first
            .map(String.init) ?? ""
        let parts = host.split(separator: ".", omittingEmptySubsequences: false)
        guard parts.count == 4 else { return nil }

        var address: UInt32 = 0
        for part in parts {
            guard let octet = UInt32(part), octet <= 255 else { return nil }
            address = (address << 8) | octet
        }
        return address
    }

    /// Parses an IPv6 peer endpoint. Both `[2001:db8::1]:6881` (the form
    /// libtorrent uses when a port is present) and a bare address are accepted;
    /// `inet_pton` rejects anything malformed.
    package static func ipv6Address(fromEndpoint endpoint: String) -> IPv6Address? {
        let host: String
        if endpoint.hasPrefix("[") {
            guard let close = endpoint.firstIndex(of: "]") else { return nil }
            host = String(endpoint[endpoint.index(after: endpoint.startIndex)..<close])
        } else {
            host = endpoint
        }
        guard host.contains(":") else { return nil }

        var raw = in6_addr()
        guard host.withCString({ inet_pton(AF_INET6, $0, &raw) }) == 1 else { return nil }

        let bytes = withUnsafeBytes(of: raw) { Array($0) }
        var high: UInt64 = 0
        var low: UInt64 = 0
        for index in 0..<8 {
            high = (high << 8) | UInt64(bytes[index])
        }
        for index in 8..<16 {
            low = (low << 8) | UInt64(bytes[index])
        }
        return IPv6Address(high: high, low: low)
    }

    /// IPv4 address carried by an IPv4-mapped IPv6 endpoint (`::ffff:a.b.c.d`).
    private static func mappedIPv4(_ address: IPv6Address) -> UInt32? {
        guard address.high == 0, (address.low >> 32) == 0xFFFF else { return nil }
        return UInt32(truncatingIfNeeded: address.low)
    }

    package static func isPrivate(_ address: IPv6Address) -> Bool {
        if address.high == 0 && (address.low == 0 || address.low == 1) {
            return true  // unspecified and loopback
        }
        if let mapped = mappedIPv4(address) {
            return isPrivate(mapped)
        }
        if address.high & 0xFE00_0000_0000_0000 == 0xFC00_0000_0000_0000 {
            return true  // unique local fc00::/7
        }
        if address.high & 0xFFC0_0000_0000_0000 == 0xFE80_0000_0000_0000 {
            return true  // link-local fe80::/10
        }
        if address.high & 0xFF00_0000_0000_0000 == 0xFF00_0000_0000_0000 {
            return true  // multicast ff00::/8
        }
        return false
    }

    package static func isPrivate(_ address: UInt32) -> Bool {
        let first = address >> 24
        let second = (address >> 16) & 0xFF
        switch first {
        case 0, 10, 127:
            return true
        case 100:
            return second >= 64 && second <= 127  // carrier-grade NAT
        case 169:
            return second == 254  // link-local
        case 172:
            return second >= 16 && second <= 31
        case 192:
            return second == 168
        default:
            return first >= 224  // multicast and reserved
        }
    }
}

/// Shared payload decoding: a little-endian `uint32` with the decompressed size
/// followed by a raw DEFLATE stream (`COMPRESSION_ZLIB` on Apple platforms
/// decodes raw deflate and rejects a zlib/gzip wrapper).
private enum GeoIPPayload {
    /// Upper bound for decompressed GeoIP tables (actual v4 + v6 tables are ~1.5 MB and ~3 MB).
    private static let maxDecompressedBytes = 16 * 1024 * 1024

    static func decompress(_ data: Data) -> [UInt8]? {
        guard data.count > 4 else { return nil }
        let expected = Int(
            UInt32(
                littleEndian: data.prefix(4).withUnsafeBytes {
                    $0.loadUnaligned(as: UInt32.self)
                })
        )
        guard expected > 0, expected <= maxDecompressedBytes else { return nil }

        var payload = [UInt8](repeating: 0, count: expected)
        let written = payload.withUnsafeMutableBytes { destination -> Int in
            data.dropFirst(4).withUnsafeBytes { source -> Int in
                guard let destinationBase = destination.bindMemory(to: UInt8.self).baseAddress,
                    let sourceBase = source.bindMemory(to: UInt8.self).baseAddress
                else {
                    return 0
                }
                return compression_decode_buffer(
                    destinationBase,
                    expected,
                    sourceBase,
                    source.count,
                    nil,
                    COMPRESSION_ZLIB
                )
            }
        }
        return written == expected ? payload : nil
    }
}

/// Sorted IPv4 ranges with an ISO country code each.
package struct GeoIPTable {
    private let codes: [String]
    private let starts: [UInt32]
    private let ends: [UInt32]
    private let indices: [UInt8]

    package static func load(from url: URL) -> GeoIPTable? {
        guard let data = try? Data(contentsOf: url) else { return nil }
        return GeoIPTable(compressed: data)
    }

    /// Format: `uint32` decompressed size followed by a raw DEFLATE stream with
    /// the country code table and the sorted ranges (see `geoip-encode.py`).
    /// `COMPRESSION_ZLIB` decodes raw deflate: it rejects a zlib/gzip wrapper.
    package init?(compressed data: Data) {
        guard let payload = GeoIPPayload.decompress(data) else { return nil }

        var cursor = 0
        func readByte() -> UInt8? {
            guard cursor < payload.count else { return nil }
            defer { cursor += 1 }
            return payload[cursor]
        }
        func readVarint() -> UInt64? {
            var value: UInt64 = 0
            var shift: UInt64 = 0
            while true {
                guard let byte = readByte(), shift < 64 else { return nil }
                value |= UInt64(byte & 0x7F) << shift
                if byte & 0x80 == 0 { return value }
                shift += 7
            }
        }

        guard let countLow = readByte(), let countHigh = readByte() else { return nil }
        let count = Int(countLow) | (Int(countHigh) << 8)
        // Indices are stored as UInt8, so at most 256 country codes can exist.
        guard count > 0, count <= 256 else { return nil }

        var codes: [String] = []
        codes.reserveCapacity(count)
        for _ in 0..<count {
            guard let first = readByte(), let second = readByte(),
                let code = String(bytes: [first, second], encoding: .ascii)
            else {
                return nil
            }
            codes.append(code)
        }

        var starts: [UInt32] = []
        var ends: [UInt32] = []
        var indices: [UInt8] = []
        var previous: UInt64 = 0
        var hasFirst = false
        while cursor < payload.count {
            guard let delta = readVarint(),
                let length = readVarint(),
                let index = readByte(),
                Int(index) < count
            else { return nil }
            let (nextStart, startOverflow) = previous.addingReportingOverflow(delta)
            guard !startOverflow, nextStart <= UInt64(UInt32.max) else { return nil }
            if hasFirst && nextStart < previous { return nil }
            hasFirst = true
            previous = nextStart
            starts.append(UInt32(previous))
            let (rawEnd, endOverflow) = previous.addingReportingOverflow(length)
            let clampedEnd = endOverflow ? UInt64(UInt32.max) : min(UInt64(UInt32.max), rawEnd)
            ends.append(UInt32(clampedEnd))
            indices.append(index)
        }
        guard !starts.isEmpty else { return nil }

        self.codes = codes
        self.starts = starts
        self.ends = ends
        self.indices = indices
    }

    package func countryCode(for address: UInt32) -> String? {
        var low = 0
        var high = starts.count - 1
        var found = -1
        while low <= high {
            let middle = (low + high) / 2
            if starts[middle] <= address {
                found = middle
                low = middle + 1
            } else {
                high = middle - 1
            }
        }
        guard found >= 0, address <= ends[found] else { return nil }
        let index = Int(indices[found])
        guard index < codes.count else { return nil }
        return codes[index]
    }
}

/// 128-bit address used by the IPv6 table. Hand-rolled because the table is
/// decoded with varints over the full address, not with `in6_addr` arithmetic.
package struct IPv6Address: Equatable, Comparable, Sendable {
    package let high: UInt64
    package let low: UInt64

    package static let zero = IPv6Address(high: 0, low: 0)

    package init(high: UInt64, low: UInt64) {
        self.high = high
        self.low = low
    }

    package static func < (lhs: IPv6Address, rhs: IPv6Address) -> Bool {
        lhs.high == rhs.high ? lhs.low < rhs.low : lhs.high < rhs.high
    }

    package static func + (lhs: IPv6Address, rhs: IPv6Address) -> IPv6Address {
        lhs.addingReportingOverflow(rhs).partialValue
    }

    package func addingReportingOverflow(_ rhs: IPv6Address) -> (partialValue: IPv6Address, overflow: Bool) {
        let (low, lowOverflow) = self.low.addingReportingOverflow(rhs.low)
        let (midHigh, highOverflow1) = self.high.addingReportingOverflow(rhs.high)
        let (high, highOverflow2) = midHigh.addingReportingOverflow(lowOverflow ? 1 : 0)
        return (IPv6Address(high: high, low: low), highOverflow1 || highOverflow2)
    }
}

/// Sorted IPv6 ranges with an ISO country code each. Same payload as
/// `GeoIPTable`, but start deltas and lengths are 128-bit varints.
package struct GeoIPv6Table {
    private let codes: [String]
    private let starts: [IPv6Address]
    private let ends: [IPv6Address]
    private let indices: [UInt8]

    package static func load(from url: URL) -> GeoIPv6Table? {
        guard let data = try? Data(contentsOf: url) else { return nil }
        return GeoIPv6Table(compressed: data)
    }

    package init?(compressed data: Data) {
        guard let payload = GeoIPPayload.decompress(data) else { return nil }

        var cursor = 0
        func readByte() -> UInt8? {
            guard cursor < payload.count else { return nil }
            defer { cursor += 1 }
            return payload[cursor]
        }
        func readVarint128() -> IPv6Address? {
            var high: UInt64 = 0
            var low: UInt64 = 0
            var shift = 0
            while true {
                guard let byte = readByte(), shift < 128 else { return nil }
                let bits = UInt64(byte & 0x7F)
                if shift < 64 {
                    low |= bits << shift
                    if shift > 57 {
                        high |= bits >> (64 - shift)
                    }
                } else {
                    if shift == 126 && (byte & 0xFC) != 0 {
                        return nil
                    }
                    high |= bits << (shift - 64)
                }
                if byte & 0x80 == 0 {
                    return IPv6Address(high: high, low: low)
                }
                shift += 7
            }
        }

        guard let countLow = readByte(), let countHigh = readByte() else { return nil }
        let count = Int(countLow) | (Int(countHigh) << 8)
        guard count > 0, count <= 256 else { return nil }

        var codes: [String] = []
        codes.reserveCapacity(count)
        for _ in 0..<count {
            guard let first = readByte(), let second = readByte(),
                let code = String(bytes: [first, second], encoding: .ascii)
            else {
                return nil
            }
            codes.append(code)
        }

        var starts: [IPv6Address] = []
        var ends: [IPv6Address] = []
        var indices: [UInt8] = []
        var previous = IPv6Address.zero
        while cursor < payload.count {
            guard let delta = readVarint128(),
                let length = readVarint128(),
                let index = readByte(),
                Int(index) < count
            else { return nil }
            let (start, startOverflow) = previous.addingReportingOverflow(delta)
            guard !startOverflow else { return nil }
            let (rawEnd, endOverflow) = start.addingReportingOverflow(length)
            let clampedEnd = endOverflow ? IPv6Address(high: .max, low: .max) : rawEnd
            starts.append(start)
            ends.append(clampedEnd)
            indices.append(index)
            previous = start
        }
        guard !starts.isEmpty else { return nil }

        self.codes = codes
        self.starts = starts
        self.ends = ends
        self.indices = indices
    }

    package func countryCode(for address: IPv6Address) -> String? {
        var low = 0
        var high = starts.count - 1
        var found = -1
        while low <= high {
            let middle = (low + high) / 2
            if starts[middle] <= address {
                found = middle
                low = middle + 1
            } else {
                high = middle - 1
            }
        }
        guard found >= 0, address <= ends[found] else { return nil }
        let index = Int(indices[found])
        guard index < codes.count else { return nil }
        return codes[index]
    }
}
